#if UNITY_EDITOR
using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System;using System.Collections.Generic;using System.IO;
public static class RetroExperimentBuilder {
 const string Root="Assets/MapTests/RetroStyle";
 [MenuItem("Editor/Pruebas/Pseudo-3D dibujado",false,2200)]public static void Open(){EditorSceneManager.OpenScene("Assets/MapTests/Codebound_RetroStyle_Test.unity");}
 static GameObject Box(string n,Transform parent,Vector3 p,Vector3 s,Material m){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=n;o.transform.SetParent(parent,false);o.transform.localPosition=p;o.transform.localScale=s;o.GetComponent<Renderer>().sharedMaterial=m;UnityEngine.Object.DestroyImmediate(o.GetComponent<Collider>());return o;}
 static Material Surface(string resource,string name,float metal,float smooth){var m=new Material(Resources.Load<Shader>("Shaders/DungeonMetalToon")){name=name};m.SetTexture("_BaseMap",Resources.Load<Texture2D>(resource));m.SetColor("_BaseColor",Color.white);m.SetFloat("_Metallic",metal);m.SetFloat("_Smoothness",smooth);m.SetFloat("_EmissionStrength",.15f);AssetDatabase.CreateAsset(m,Root+"/"+name+".mat");return m;}
 public static string Build(){if(File.Exists("Assets/MapTests/Codebound_RetroStyle_Test.unity"))throw new Exception("La escena ya existe");foreach(var name in new[]{"Tapaku","Chest"}){string path=Root+"/Sprites/"+name+".png";AssetDatabase.ImportAsset(path);var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.isReadable=true;ti.mipmapEnabled=false;ti.filterMode=FilterMode.Point;ti.textureCompression=TextureImporterCompression.Uncompressed;ti.npotScale=TextureImporterNPOTScale.None;ti.SaveAndReimport();}
  var map=ScriptableObject.CreateInstance<DungeonMapSettings>();map.includeLegacyObjects=false;map.startCell=new Vector2Int(3,2);map.startHeading=0;int w=24,h=24;char[][] cells=new char[h][];for(int y=0;y<h;y++){cells[y]=new char[w];for(int x=0;x<w;x++)cells[y][x]='#';}Action<int,int,int,int> carve=(a,b,c,d)=>{for(int y=b;y<=d;y++)for(int x=a;x<=c;x++)cells[y][x]='.';};carve(3,1,3,8);carve(3,8,10,8);carve(8,7,12,11);carve(10,11,10,15);carve(7,15,19,21);carve(14,11,14,18);carve(10,13,17,13);carve(17,11,20,13);map.rows=new string[h];for(int y=0;y<h;y++)map.rows[y]=new string(cells[y]);var objects=ScriptableObject.CreateInstance<DungeonEntitySettings>();objects.objects.Add(new DungeonMapEntity{id="retro.door",displayName="Puerta experimental",kind=DungeonEntityKind.Door,cell=new Vector2Int(10,12),heading=0});map.entities=objects;AssetDatabase.CreateAsset(objects,Root+"/Objects.asset");AssetDatabase.CreateAsset(map,Root+"/Map.asset");
  var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var holder=new GameObject("EXPERIMENTO — seleccionar para ajustar");var blocker=holder.AddComponent<DungeonPrototype>();blocker.enabled=false;blocker.hideFlags=HideFlags.HideInInspector;var e=holder.AddComponent<RetroDungeonExperiment>();e.map=map;e.decorations=new[]{new RetroDecoration{label="Tapaku",cell=new Vector2Int(3,7),texture=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Sprites/Tapaku.png"),heightCells=.66f},new RetroDecoration{label="Cofre",cell=new Vector2Int(11,10),texture=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Sprites/Chest.png"),heightCells=.35f}};
  var presentation=new GameObject("Presentation Camera — composición2D");var display=presentation.AddComponent<Camera>();display.cullingMask=0;display.backgroundColor=Color.black;display.clearFlags=CameraClearFlags.SolidColor;display.orthographic=true;display.depth=-10;presentation.tag="MainCamera";presentation.AddComponent<AudioListener>();var reference=new GameObject("Reference Camera — independiente");var cam=reference.AddComponent<Camera>();cam.fieldOfView=68;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.allowHDR=false;cam.allowMSAA=false;cam.enabled=false;e.referenceCamera=cam;
  var geometry=new GameObject("A — geometría independiente");e.referenceGeometry=geometry;var light=new GameObject("Main Light");light.transform.SetParent(geometry.transform);var sun=light.AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=.8f;sun.shadows=LightShadows.None;light.transform.rotation=Quaternion.Euler(45,30,0);
  var wall=Surface("Textures/textura azul luffy2","Reference-Wall",.55f,.8f);wall.SetFloat("_ContinuousWallGrid",1);wall.SetVector("_FloorGridRegion",new Vector4(266f/1254,260f/1254,144f/1254,144f/1254));wall.SetFloat("_FloorGridSize",3f/9);var floor=Surface("Textures/textura rosa luffy2","Reference-Floor",.55f,.7f);floor.SetFloat("_ContinuousFloorGrid",1);floor.SetVector("_FloorGridRegion",new Vector4(266f/1254,850f/1254,146f/1254,143f/1254));floor.SetFloat("_FloorGridSize",3f/9);var ceiling=Surface("Textures/textura rosa luffy2","Reference-Ceiling",.35f,.6f);
  for(int y=0;y<h;y++)for(int x=0;x<w;x++){var p=new Vector3(x*3,0,y*3);if(map.rows[y][x]=='#')Box("Wall",geometry.transform,p+Vector3.up*1.5f,new Vector3(3,3,3),wall);else{Box("Floor",geometry.transform,p-Vector3.up*.1f,new Vector3(3,.2f,3),floor);Box("Ceiling",geometry.transform,p+Vector3.up*3.1f,new Vector3(3,.2f,3),ceiling);}}
  var doorMaterial=new Material(Shader.Find("Universal Render Pipeline/Unlit")){name="Reference-Door"};doorMaterial.SetColor("_BaseColor",new Color(.055f,.12f,.22f));AssetDatabase.CreateAsset(doorMaterial,Root+"/Reference-Door.mat");var doorRoot=new GameObject("Experimental door");doorRoot.transform.SetParent(geometry.transform);doorRoot.transform.localPosition=new Vector3(30,0,37.5f);var door=Box("Panel",doorRoot.transform,new Vector3(0,1.5f,0),new Vector3(2.9f,3,.1f),doorMaterial);e.referenceDoorPanels=new[]{door.transform};e.referenceDoorIds=new[]{"retro.door"};
  var sprites=new List<Transform>();foreach(var deco in e.decorations){var o=new GameObject(deco.label);o.transform.SetParent(geometry.transform);o.transform.localPosition=new Vector3(deco.cell.x*3,deco.heightCells*1.5f,deco.cell.y*3);var sr=o.AddComponent<SpriteRenderer>();var sp=Sprite.Create(deco.texture,new Rect(0,0,deco.texture.width,deco.texture.height),new Vector2(.5f,.5f),deco.texture.height/(deco.heightCells*3));sp.name=deco.label;AssetDatabase.CreateAsset(sp,Root+"/Sprites/"+deco.label+".asset");sr.sprite=sp;sr.sharedMaterial=new Material(Resources.Load<Shader>("Shaders/EnemySprite"));sr.sharedMaterial.SetTexture("_BaseMap",deco.texture);AssetDatabase.CreateAsset(sr.sharedMaterial,Root+"/Sprites/"+deco.label+".mat");sprites.Add(o.transform);}e.referenceSprites=sprites.ToArray();geometry.SetActive(false);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,"Assets/MapTests/Codebound_RetroStyle_Test.unity");Selection.activeGameObject=holder;return "Escena independiente creada";
 }
}
